defmodule Type do
  @valid_enum_members [
    :PushEvent,
    :CreateEvent,
    :WatchEvent,
    :PullRequestEvent,
    :DeleteEvent,
  ]

  def valid_atom?(value), do: value in @valid_enum_members

  def valid_atom_string?(value) do
    try do
        atom = String.to_existing_atom(value)
        atom in @valid_enum_members
    rescue
        ArgumentError -> false
    end
  end

  def encode(value) do
    if valid_atom?(value) do
        Atom.to_string(value)
    else
        {:error, "Unexpected value when encoding atom: #{inspect(value)}"}
    end
  end

  def decode(value) do
    if valid_atom_string?(value) do
        String.to_existing_atom(value)
    else
        {:error, "Unexpected value when decoding atom: #{inspect(value)}"}
    end
  end

  def from_json(json) do
    json
    |> Jason.decode!()
    |> decode()
  end

  def to_json(data) do
    data
    |> encode()
    |> Jason.encode!()
  end
end

defmodule TopLevelElement do
  @enforce_keys [:actor, :created_at, :id, :payload, :public, :repo, :type]
  defstruct [:actor, :created_at, :id, :org, :payload, :public, :repo, :type]

  @type t :: %__MODULE__{
          actor: Actor.t(),
          created_at: String.t(),
          id: String.t(),
          org: Actor.t() | nil,
          payload: Payload.t(),
          public: boolean(),
          repo: TopLevelRepo.t(),
          type: Type.t()
        }

  def decode_created_at(value) when is_binary(value), do: value
  def decode_created_at(_), do: {:error, "Unexpected type when decoding TopLevelElement.created_at"}

  def encode_created_at(value) when is_binary(value), do: value
  def encode_created_at(_), do: {:error, "Unexpected type when encoding TopLevelElement.created_at"}

  def decode_id(value) when is_binary(value), do: value
  def decode_id(_), do: {:error, "Unexpected type when decoding TopLevelElement.id"}

  def encode_id(value) when is_binary(value), do: value
  def encode_id(_), do: {:error, "Unexpected type when encoding TopLevelElement.id"}

  def decode_public(value) when is_boolean(value), do: value
  def decode_public(_), do: {:error, "Unexpected type when decoding TopLevelElement.public"}

  def encode_public(value) when is_boolean(value), do: value
  def encode_public(_), do: {:error, "Unexpected type when encoding TopLevelElement.public"}

  def from_map(m) do
    %TopLevelElement{
      actor: Actor.from_map(m["actor"]),
      created_at: decode_created_at(m["created_at"]),
      id: decode_id(m["id"]),
      org: m["org"] && Actor.from_map(m["org"]),
      payload: Payload.from_map(m["payload"]),
      public: decode_public(m["public"]),
      repo: TopLevelRepo.from_map(m["repo"]),
      type: Type.decode(m["type"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "actor" => Actor.to_map(struct.actor),
      "created_at" => struct.created_at,
      "id" => struct.id,
      "org" => struct.org && Actor.to_map(struct.org),
      "payload" => Payload.to_map(struct.payload),
      "public" => struct.public,
      "repo" => TopLevelRepo.to_map(struct.repo),
      "type" => Type.encode(struct.type),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

defmodule TopLevel do
  def from_json(json) do
    json
    |> Jason.decode!()
    |> Enum.map(&TopLevelElement.from_map/1)
  end

  def to_json(list) do
    Enum.map(list, &TopLevelElement.to_map/1)
    |> Jason.encode!()
  end
end
